        else:
            j = rng.randrange(n)
            if assign[i] == assign[j]:
                continue
            assign[i], assign[j] = assign[j], assign[i]
            c = _cost(assign, models, gpu_num)
            if c < cur or (c < float('inf') and rng.random() < math.exp((cur - c) / T)):
